<?php
namespace ZinCelestial\Platform\Admin;use ZinCelestial\Platform\Fleet\FleetService;defined('ABSPATH')||exit;
final class FleetPage{public function register():void{add_action('network_admin_menu',array($this,'menu'));}public function menu():void{add_submenu_page('zcp-network',__('Fleet Management','zincelestial-platform'),__('Fleet','zincelestial-platform'),'manage_network_options','zcp-fleet',array($this,'render'));}public function render():void{if(!current_user_can('manage_network_options'))return;$d=(new FleetService())->dashboard();$s=$d['summary'];echo '<div class="wrap zcp-admin"><header class="zcp-hero"><div><h1>'.esc_html__('Fleet Management','zincelestial-platform').'</h1><p>'.esc_html__('Network-wide site inventory and Platform version posture.','zincelestial-platform').'</p></div></header><div class="zcp-summary"><article><strong>'.esc_html((string)$s['discovered']).'</strong><span>'.esc_html__('Discovered sites','zincelestial-platform').'</span></article><article><strong>'.esc_html((string)$s['stale']).'</strong><span>'.esc_html__('Stale reports','zincelestial-platform').'</span></article></div><table class="widefat striped"><thead><tr><th>'.esc_html__('Site','zincelestial-platform').'</th><th>'.esc_html__('URL','zincelestial-platform').'</th><th>'.esc_html__('Platform','zincelestial-platform').'</th><th>'.esc_html__('Theme','zincelestial-platform').'</th><th>'.esc_html__('Updated','zincelestial-platform').'</th></tr></thead><tbody>';foreach($d['sites'] as $r)echo '<tr><td>'.esc_html((string)$r['site_id']).'</td><td>'.esc_html($r['url']).'</td><td>'.esc_html($r['platform_version']).'</td><td>'.esc_html($r['theme']).'</td><td>'.esc_html(wp_date('Y-m-d H:i',(int)$r['updated'])).'</td></tr>';echo '</tbody></table></div>';}}
